  empty.secondaryRadius = sourceRadius(secondaryMotion, shutter);
  empty.valid = empty.primaryRadius > 1e-5 || empty.secondaryRadius > 1e-5;
  empty.longVector = max(empty.primaryRadius, empty.secondaryRadius) > 8.0;
